function c(){const a=new WeakMap,o=new WeakMap;return{add_attr:(t,e,s)=>{let r=a.get(t);r||(r=new Map,a.set(t,r)),r.has(e)||r.set(e,t.getAttribute(e)),t.setAttribute(e,s)},remove_attrs:t=>{const e=a.get(t);if(e){for(const[s,r]of e)r===null?t.removeAttribute(s):t.setAttribute(s,r);a.delete(t)}},mapped_elements_for_root:t=>{let e=o.get(t);return e||(e=new Set,o.set(t,e)),e},delete_root:t=>{o.delete(t)}}}export{c};
